private static void assertSubstitutionChain(Expression e, List<Class<? extends Expression>> substitutionChain) {
        var currentExpression = e;

        for (Class<? extends Expression> currentSubstitution : substitutionChain.subList(0, substitutionChain.size() - 1)) {
            assertThat(currentExpression, instanceOf(currentSubstitution));
            assertEquals(currentExpression.children().size(), 1);
            currentExpression = currentExpression.children().get(0);
        }

        assertThat(currentExpression, instanceOf(substitutionChain.get(substitutionChain.size() - 1)));
    }

@Override
    public Expression surrogate() {
        var s = source();
        var field = field();

        if (field.foldable()) {
            if (field instanceof Literal l) {
                if (l.value() != null && (l.value() instanceof List<?>) == false) {
                    // TODO: Normalize COUNT(*), COUNT(), COUNT("foobar"), COUNT(1) as COUNT(*).
                    // Does not apply to COUNT([1,2,3])
                    // return new Count(s, new Literal(s, StringUtils.WILDCARD, DataTypes.KEYWORD));
                    return null;
                }
            }

            // COUNT(const) is equivalent to MV_COUNT(const)*COUNT(*) if const is not null; otherwise COUNT(const) == 0.
            return new Mul(
                s,
                new Coalesce(s, new MvCount(s, field), List.of(new Literal(s, 0, DataTypes.INTEGER))),
                new Count(s, new Literal(s, StringUtils.WILDCARD, DataTypes.KEYWORD))
            );
        }

        return null;
    }

@Override
    public Expression surrogate() {
        var s = source();
        var field = field();

        return field.foldable()
            ? new ToLong(s, new Coalesce(s, new MvCount(s, new MvDedupe(s, field)), List.of(new Literal(s, 0, DataTypes.INTEGER))))
            : null;
    }

private static boolean oneLeaveIsNull(Expression e) {
        Holder<Boolean> result = new Holder<>(false);

        e.forEachUp(node -> {
            if (node.children().size() == 0) {
                result.set(result.get() || Expressions.isNull(node));
            }
        });

        return result.get();
    }

